"""Second question types for Heat Transfer (HT)."""
from opl_dsl import Q

FILE, FRAMEWORK = "ht-second-types", "heat-transfer"
SIG = "Rational(5670374, 10**14)"   # Stefan-Boltzmann, W/(m^2 K^4)
